185	    23	    public String generate(LocalDate night) {
186	    24	        List<Reservation> occupying = new ArrayList<>();
187	    25	        for (Reservation reservation : store.all()) {
188	    26	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
189	    27	            if (reservation.isPaid() && coversNight) {
190	    28	                occupying.add(reservation);
191	    29	            }
192	    30	        }
193	    31	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
194	    32	
195	    33	        StringBuilder csv = new StringBuilder();
196	    34	        csv.append("room,type,reservation,check_in,check_out\n");
197	    35	        for (Reservation reservation : occupying) {
198	    36	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
199	    37	            csv.append(room.number()).append(',')
200	    38	                    .append(room.type()).append(',')
201	    39	                    .append(reservation.id()).append(',')
202	    40	                    .append(reservation.checkIn()).append(',')
203	    41	                    .append(reservation.checkOut()).append('\n');
204	    42	        }
205	    43	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
